package dev.raven.backup;
import android.app.*;import android.content.*;import android.os.*;import android.view.accessibility.*;import java.util.*;import java.util.concurrent.atomic.*;
/** Checks new settings and both schedule/password prompts without enabling a real schedule. */
public final class FeatureUiTest extends Instrumentation {
 android.widget.TextView find(android.view.View v,String label){if(v instanceof android.widget.TextView&&label.contentEquals(((android.widget.TextView)v).getText()))return (android.widget.TextView)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)v;for(int i=0;i<group.getChildCount();i++){android.widget.TextView found=find(group.getChildAt(i),label);if(found!=null)return found;}}return null;}
 void require(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 AccessibilityNodeInfo node(String text)throws Exception{for(int i=0;i<20;i++){Thread.sleep(150);AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null){java.util.List<AccessibilityNodeInfo> nodes=root.findAccessibilityNodeInfosByText(text);if(!nodes.isEmpty())return nodes.get(0);}}return null;}
 String describe(AccessibilityNodeInfo node){if(node==null)return "null";StringBuilder text=new StringBuilder(String.valueOf(node.getText())+";");for(int i=0;i<node.getChildCount();i++)text.append(describe(node.getChild(i)));return text.toString();}
 void click(String text)throws Exception{AccessibilityNodeInfo n=node(text);require(n!=null,"No button "+text);require(n.performAction(AccessibilityNodeInfo.ACTION_CLICK),"Could not click "+text);}
 public void onStart(){Bundle out=new Bundle();try{getUiAutomation();Context c=getTargetContext();require(!OperationService.running()&&!ScheduledBackupService.running&&!new LiveRestore(c).pointer.exists(),"Active operation");android.content.SharedPreferences prefs=RestorePreferences.prefs(c),schedule=BackupSchedule.prefs(c);Map<String,?> original=prefs.getAll(),oldSchedule=schedule.getAll();MainActivity a=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{
  runOnMainSync(()->a.showSection("Settings"));waitForIdleSync();require(find(a.content,"Verify completed backups")!=null,"Verification toggle missing");require(find(a.content,"Encrypt future backups")!=null,"Encryption toggle missing");
  schedule.edit().putString("config","{}").commit();runOnMainSync(()->a.setBackupPassword(null));waitForIdleSync();require(node("Scheduled backups and passwords")!=null,"Password schedule reminder missing");click("Keep off");AccessibilityNodeInfo remember=node("Remember password on this device");require(remember!=null&&!remember.isChecked(),"Remember default not off");click("Cancel");
  schedule.edit().remove("config").commit();prefs.edit().putBoolean(ArchiveVerifier.ENCRYPT,true).commit();runOnMainSync(()->a.configureSchedule(Collections.singletonList("dev.raven.backup.setupfixture")));require(node("Scheduled backups need a saved password")!=null,"Encrypted schedule gate missing");click("Cancel");
  prefs.edit().putBoolean(ArchiveVerifier.ENCRYPT,false).commit();AtomicBoolean enabled=new AtomicBoolean();runOnMainSync(()->a.confirmSchedulePassword(()->enabled.set(true)));require(node("These scheduled backups will be unencrypted")!=null,"Plain schedule password guidance missing");click("Cancel");require(!enabled.get(),"Cancel enabled schedule");waitForIdleSync();Thread.sleep(100);require(a.openDialogs==0,"Dialog tracking did not reset");out.putString("result","PASS settings controls, password reminder with configured schedule, Keep off preserves default, missing-password schedule prompt, schedule encryption guidance and Cancel no-op");
 }finally{SettingsTransfer.restore(prefs,original);SettingsTransfer.restore(schedule,oldSchedule);runOnMainSync(()->a.showSection("Settings"));}finish(-1,out);
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));out.putString("ui_tree",describe(getUiAutomation().getRootInActiveWindow()));finish(0,out);}}
}
